$$('.br').forEach(function(b){b.classList.add('in')});$('#stBad').className='st fx';$('#emOnly').textContent='Three days only.';$$('#emS .box').forEach(function(b){b.className='box on'});
var f=$('#fix');f.classList.add('in','done');$('#v1').className='';$('#v2').className='on';tag('Copy · Admit','g');wait('Waiting on you','');$('#dec').textContent='1 decision on v2';var a=$('#appr');a.className='btn ready';a.textContent='Approve v2';
